package com.example.rokidkeyboardbridge;
import android.content.*;import android.graphics.*;import java.io.*;import java.util.*;import java.util.zip.*;
/** Synthetic source decoding and actual View/Canvas rendering. No user inputs or capture. */
public final class HeadEarDeviceChecks {
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}
 public static int run(Context system,String apk)throws Exception{
  AvatarPipelineDeviceChecks.normalInspection(system);Context c=RestArtworkDeviceChecks.assets(system,apk);FullBodyMascotView view=new FullBodyMascotView(c);view.layout(0,0,240,600);int[] ids={8,17,22,24,25,4};Bitmap sheet=Bitmap.createBitmap(240*6,600,Bitmap.Config.ARGB_8888);Canvas grid=new Canvas(sheet);grid.drawColor(Color.BLACK);
  try(ZipFile zip=new ZipFile(apk)){for(int i=0;i<ids.length;i++){Bitmap source=FullBodyRealisticAssets.decode(zip,ids[i],1),frame=Bitmap.createBitmap(240,600,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(frame);canvas.drawColor(Color.BLACK);view.renderInspection(canvas,source,ids[i],1600,false,false,null,0,0);int top=600,count=0;for(int y=0;y<600;y++)for(int x=0;x<240;x++)if((frame.getPixel(x,y)&0xffffff)!=0){top=Math.min(top,y);count++;}ok(count>3000,"figure remains visible "+ids[i]);ok(top>=7&&top<100,"head has clear top margin "+ids[i]+" top="+top);grid.drawBitmap(frame,i*240,0,null);frame.recycle();source.recycle();}}
  try(FileOutputStream f=new FileOutputStream(new File(system.getFilesDir(),"head-v689-native.png"))){sheet.compress(Bitmap.CompressFormat.PNG,100,f);}sheet.recycle();view.releaseInspection();
  for(int clip:new int[]{3,7}){FullBodyGestureRenderer ear=new FullBodyGestureRenderer(new FullBodyGestureCanvasTest.Host(c));ok(FullBodyGestureRenderer.assetForClip(clip).equals(SeatedGestureAtlas.asset(clip)),"only seated earring uses corrected asset");ok(!FullBodyGestureRenderer.assetForClip(2).equals(SeatedGestureAtlas.EAR),"standing earring remains separate");ear.request(clip);long end=System.currentTimeMillis()+15000;while(!ear.ready(clip)&&System.currentTimeMillis()<end)Thread.sleep(10);ok(ear.ready(clip),"corrected ear atlas decodes");Bitmap preview=Bitmap.createBitmap(240*4,600,Bitmap.Config.ARGB_8888);Canvas out=new Canvas(preview);out.drawColor(Color.BLACK);Set<Integer> distinct=new HashSet<>();
  long[] times={0,550,1300,2600};for(int i=0;i<times.length;i++){Bitmap b=Bitmap.createBitmap(240,600,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);canvas.drawColor(Color.BLACK);ok(ear.draw(canvas,240,600,clip,times[i],100000+times[i]),"ear keyframe renders");int[] pixels=new int[240*600];b.getPixels(pixels,0,240,0,0,240,600);distinct.add(Arrays.hashCode(pixels));int first=600;for(int y=0;y<600;y++)for(int x=0;x<240;x++)if((pixels[y*240+x]&0xffffff)!=0)first=Math.min(first,y);ok(first>=7,"seated crown remains visible");out.drawBitmap(b,i*240,0,null);b.recycle();}ok(distinct.size()==4,"four distinct continuous ear frames");ear.release();
  try(FileOutputStream f=new FileOutputStream(new File(system.getFilesDir(),clip==3?"ear-v689-native.png":"beckon-v689-native.png"))){preview.compress(Bitmap.CompressFormat.PNG,100,f);}preview.recycle();}return n;
 }
}
